<template><div class="post-page"><template v-if="post"><header class="post-hero" :class="{withCover:post.coverUrl}" :style="post.coverUrl?{backgroundImage:`linear-gradient(90deg,rgba(31,27,58,.86),rgba(60,52,98,.52)),url(${post.coverUrl})`}:{}"><div class="post-hero-inner"><router-link to="/blog">← 返回工作记录</router-link><div class="post-meta"><span>{{post.category||'随笔'}}</span><time>{{date(post.publishedAt)}}</time><span>◉ {{post.viewCount}} 次阅读</span></div><h1>{{post.title}}</h1><p v-if="post.summary">{{post.summary}}</p><div class="post-tags"><span v-for="item in tags" :key="item"># {{item}}</span></div></div></header><section class="reading-shell"><aside><div class="author-mini"><div>WR</div><span><b>工作记录</b><small>沉淀项目与工程经验</small></span></div><router-link to="/blog">更多文章 <i>→</i></router-link></aside><article class="post-content"><MarkdownContent :content="post.markdownContent"/></article></section><footer class="post-end"><span>WORK NOTES · END</span><h3>感谢你读到这里。</h3><p>愿这篇记录，也能成为你下一次出发的坐标。</p><router-link to="/blog">继续浏览文章 →</router-link></footer></template><el-skeleton v-else class="post-loading" :rows="10" animated/></div></template>
<script setup lang="ts">import{computed,onMounted,ref,watch}from'vue';import{useRoute}from'vue-router';import{getPublicBlogPost,type BlogPost}from'@/api/blog';import MarkdownContent from'@/components/MarkdownContent.vue';const route=useRoute(),post=ref<BlogPost>();const tags=computed(()=>post.value?.tags?.split(',').map(x=>x.trim()).filter(Boolean)||[]);const date=(v:string|null)=>v?new Date(v).toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric'}):'';async function load(){post.value=(await getPublicBlogPost(String(route.params.slug),'WORK')).data;document.title=`${post.value.seoTitle||post.value.title} · 工作记录`;document.querySelector('meta[name="description"]')?.setAttribute('content',post.value.seoDescription||post.value.summary||'工作记录博客文章');window.scrollTo({top:0});}onMounted(load);watch(()=>route.params.slug,load);</script>
<style scoped>.post-page{min-height:100vh}.post-hero{position:relative;min-height:430px;padding:150px 24px 65px;color:#fff;background:radial-gradient(circle at 82% 22%,rgb(255 255 255 / 15%),transparent 14%),linear-gradient(125deg,#37305e,#776dab 62%,#aca4cf)}.post-hero.withCover{background-position:center;background-size:cover}.post-hero-inner{max-width:880px;margin:auto}.post-hero-inner>a{display:inline-flex;margin-bottom:38px;color:rgb(255 255 255 / 75%);font-size:12px;font-weight:700;text-decoration:none}.post-meta{display:flex;flex-wrap:wrap;gap:12px;align-items:center;color:rgb(255 255 255 / 70%);font-size:11px}.post-meta span:first-child{padding:5px 9px;color:#fff;background:rgb(255 255 255 / 16%);border:1px solid rgb(255 255 255 / 15%);border-radius:7px}.post-hero h1{max-width:820px;margin:20px 0 15px;font-family:"Songti SC",Georgia,serif;font-size:48px;font-weight:650;line-height:1.3;letter-spacing:.01em;text-shadow:0 8px 28px rgb(24 20 54 / 24%)}.post-hero p{max-width:700px;margin:0;color:rgb(255 255 255 / 78%);font-size:15px;line-height:1.8}.post-tags{display:flex;flex-wrap:wrap;gap:8px;margin-top:22px}.post-tags span{padding:5px 8px;color:rgb(255 255 255 / 72%);background:rgb(255 255 255 / 10%);border-radius:6px;font-size:10px}.reading-shell{display:grid;grid-template-columns:190px minmax(0,760px);gap:42px;max-width:1040px;padding:46px 22px 20px;margin:auto}.reading-shell aside{position:sticky;top:110px;height:max-content;padding:17px;background:var(--surface);border:1px solid var(--line);border-radius:17px;box-shadow:var(--shadow)}.author-mini{display:flex;gap:10px;align-items:center;padding-bottom:14px;border-bottom:1px solid var(--line)}.author-mini>div{display:grid;width:38px;height:38px;color:#fff;font-size:12px;font-weight:900;place-items:center;background:linear-gradient(145deg,#9386ec,#6253d3);border-radius:50%}.author-mini span{display:flex;flex-direction:column;gap:3px}.author-mini b{font-size:12px}.author-mini small{color:var(--muted);font-size:9px}.reading-shell aside>a{display:flex;justify-content:space-between;margin-top:14px;color:var(--primary);font-size:11px;font-weight:750;text-decoration:none}.reading-shell aside i{font-style:normal}.post-content{min-width:0;padding:3px 0 25px}.post-end{max-width:760px;padding:46px 20px 55px;margin:32px auto 0;text-align:center;border-top:1px solid var(--line)}.post-end>span{color:var(--primary);font-size:9px;font-weight:850;letter-spacing:.25em}.post-end h3{margin:13px 0 7px;font-family:"Songti SC",Georgia,serif;font-size:23px}.post-end p{color:var(--muted);font-size:13px}.post-end a{display:inline-block;margin-top:14px;color:var(--primary);font-size:13px;font-weight:750;text-decoration:none}.post-loading{max-width:900px;padding:150px 24px;margin:auto}@media(max-width:800px){.post-hero{min-height:390px;padding:125px 22px 52px}.post-hero h1{font-size:38px}.reading-shell{display:block;padding-top:30px}.reading-shell aside{position:static;display:flex;align-items:center;justify-content:space-between;margin-bottom:28px}.reading-shell aside>a{gap:15px;margin:0}.author-mini{padding:0;border:0}}@media(max-width:520px){.post-hero{min-height:360px;padding:110px 18px 42px}.post-hero-inner>a{margin-bottom:28px}.post-hero h1{font-size:31px}.post-hero p{font-size:14px}.reading-shell{padding:25px 18px 10px}.post-end{margin-top:15px}}
